import { t } from '../i18n/index';
import { LAppDelegate } from '../delegation/delegate';
import { setUIElementActive } from './state';
import { BackgroundMode, BackgroundState, saveBackgroundState, loadBackgroundState, hexToRgb, mixHexColors, applyBackgroundState, getPrimaryView } from './background';


export function setupControlBarUI(): void {
    const bgBtn = document.getElementById('btn-bg-picker') as HTMLButtonElement | null;
    const bgInput = document.getElementById('bg-color-input') as HTMLInputElement | null;
    const resetBtn = document.getElementById('btn-reset-view') as HTMLButtonElement;
    const zoomInBtn = document.getElementById('btn-zoom-in') as HTMLButtonElement;
    const zoomOutBtn = document.getElementById('btn-zoom-out') as HTMLButtonElement;
    if (!resetBtn || !zoomInBtn || !zoomOutBtn) {
        console.warn('Control bar buttons not found. Skipping control wiring.');
        return;
    }
    const toggleWindowBtn = document.getElementById('toggle-window-btn') as HTMLButtonElement;
    const toggleParamsBtn = document.getElementById('toggle-params-btn') as HTMLButtonElement;
    const toggleExprBtn = document.getElementById('toggle-expr-btn') as HTMLButtonElement;
    const importBtn = document.getElementById('import-model-btn') as HTMLButtonElement;
    const setActive = (v: boolean) => setUIElementActive(v);
    const interactiveEls: HTMLElement[] = [resetBtn, zoomInBtn, zoomOutBtn, toggleWindowBtn, toggleParamsBtn, toggleExprBtn];
    if (bgBtn) interactiveEls.push(bgBtn);
    if (importBtn) interactiveEls.push(importBtn);
    interactiveEls.forEach((el) => {
        el.addEventListener('pointerdown', () => setActive(true), { passive: true });
        el.addEventListener('pointerup', () => setActive(false), { passive: true });
        el.addEventListener('pointerleave', () => setActive(false), { passive: true });
        el.addEventListener('touchstart', () => setActive(true), { passive: true });
        el.addEventListener('touchend', () => setActive(false), { passive: true });
    });
    
    resetBtn.addEventListener('click', () => {
        const view = getPrimaryView();
        if (!view) return;
        view.resetView();
    });
    zoomInBtn.addEventListener('click', () => {
        const view = getPrimaryView();
        if (!view) return;
        const appDelegate = LAppDelegate.getInstance();
        const subs = appDelegate.getSubdelegates();
        if (!subs || subs.length === 0) return;
        const sub = subs[0];
        if (!sub) return;
        const canvas = sub.getCanvas();
        const cx = canvas.width * 0.5;
        const cy = canvas.height * 0.5;
        view.zoomByFactor(1.15, cx, cy);
    });
    zoomOutBtn.addEventListener('click', () => {
        const view = getPrimaryView();
        if (!view) return;
        const appDelegate = LAppDelegate.getInstance();
        const subs = appDelegate.getSubdelegates();
        if (!subs || subs.length === 0) return;
        const sub = subs[0];
        if (!sub) return;
        const canvas = sub.getCanvas();
        const cx = canvas.width * 0.5;
        const cy = canvas.height * 0.5;
        view.zoomByFactor(1.0 / 1.15, cx, cy);
    });
    const bgWindow = document.getElementById('bg-window') as HTMLDivElement | null;
    const modeSolid = document.getElementById('bg-mode-solid') as HTMLInputElement | null;
    const modeGradient = document.getElementById('bg-mode-gradient') as HTMLInputElement | null;
    const modeImage = document.getElementById('bg-mode-image') as HTMLInputElement | null;
    const solidInput = document.getElementById('bg-solid-color') as HTMLInputElement | null;
    const gradStartInput = document.getElementById('bg-grad-start') as HTMLInputElement | null;
    const gradEndInput = document.getElementById('bg-grad-end') as HTMLInputElement | null;
    const gradAngleInput = document.getElementById('bg-grad-angle') as HTMLInputElement | null;
    const gradAngleLabel = document.getElementById('bg-grad-angle-label') as HTMLSpanElement | null;
    const imageInput = document.getElementById('bg-image-input') as HTMLInputElement | null;
    const imageClearBtn = document.getElementById('bg-image-clear') as HTMLButtonElement | null;
    const bgCloseBtn = document.getElementById('bg-close-btn') as HTMLButtonElement | null;
    const sectionSolid = document.getElementById('bg-section-solid') as HTMLDivElement | null;
    const sectionGradient = document.getElementById('bg-section-gradient') as HTMLDivElement | null;
    const sectionImage = document.getElementById('bg-section-image') as HTMLDivElement | null;
    const savedBg = localStorage.getItem('app_bg_color') || '#ffffff';
    
    let bgState = loadBackgroundState(savedBg);
    const updateBackgroundUi = (state: BackgroundState) => {
        if (sectionSolid) sectionSolid.classList.toggle('active', state.mode === 'solid');
        if (sectionGradient) sectionGradient.classList.toggle('active', state.mode === 'gradient');
        if (sectionImage) sectionImage.classList.toggle('active', state.mode === 'image');
        if (modeSolid) modeSolid.checked = state.mode === 'solid';
        if (modeGradient) modeGradient.checked = state.mode === 'gradient';
        if (modeImage) modeImage.checked = state.mode === 'image';
        const tabs = Array.from(
            document.querySelectorAll<HTMLLabelElement>('#bg-window .bg-mode-tab')
        );
        tabs.forEach((tab) => {
            const mode = tab.dataset.mode as BackgroundMode | undefined;
            tab.classList.toggle('active', mode === state.mode);
        });
    };
    
    if (solidInput) solidInput.value = bgState.solidColor;
    if (gradStartInput) gradStartInput.value = bgState.gradientStart;
    if (gradEndInput) gradEndInput.value = bgState.gradientEnd;
    if (gradAngleInput) gradAngleInput.value = String(bgState.gradientAngle);
    if (gradAngleLabel) gradAngleLabel.textContent = `${t('bg.angle')} ${bgState.gradientAngle}°`;
    if (modeSolid) modeSolid.checked = bgState.mode === 'solid';
    if (modeGradient) modeGradient.checked = bgState.mode === 'gradient';
    if (modeImage) modeImage.checked = bgState.mode === 'image';
    updateBackgroundUi(bgState);
    applyBackgroundState(bgState);
    setTimeout(() => applyBackgroundState(bgState), 500);
    setTimeout(() => applyBackgroundState(bgState), 1500);
    const setMode = (mode: BackgroundMode) => {
        bgState.mode = mode;
        saveBackgroundState(bgState);
        updateBackgroundUi(bgState);
        applyBackgroundState(bgState);
    };
    if (modeSolid) {
        modeSolid.addEventListener('change', () => {
            if (modeSolid.checked) setMode('solid');
        });
    }
    if (modeGradient) {
        modeGradient.addEventListener('change', () => {
            if (modeGradient.checked) setMode('gradient');
        });
    }
    if (modeImage) {
        modeImage.addEventListener('change', () => {
            if (modeImage.checked) setMode('image');
        });
    }
    if (solidInput) {
        solidInput.addEventListener('input', (ev) => {
            const val = (ev.target as HTMLInputElement).value || '#ffffff';
            bgState.solidColor = val;
            localStorage.setItem('app_bg_color', val);
            saveBackgroundState(bgState);
            if (bgState.mode === 'solid') {
                applyBackgroundState(bgState);
            }
        });
    }
    if (gradStartInput) {
        gradStartInput.addEventListener('input', (ev) => {
            const val = (ev.target as HTMLInputElement).value || '#ffffff';
            bgState.gradientStart = val;
            saveBackgroundState(bgState);
            if (bgState.mode === 'gradient') {
                applyBackgroundState(bgState);
            }
        });
    }
    if (gradEndInput) {
        gradEndInput.addEventListener('input', (ev) => {
            const val = (ev.target as HTMLInputElement).value || '#ffffff';
            bgState.gradientEnd = val;
            saveBackgroundState(bgState);
            if (bgState.mode === 'gradient') {
                applyBackgroundState(bgState);
            }
        });
    }
    if (gradAngleInput) {
        gradAngleInput.addEventListener('input', (ev) => {
            const raw = (ev.target as HTMLInputElement).value;
            const num = parseFloat(raw);
            if (!isNaN(num)) {
                let angle = num;
                if (angle < 0) angle = 0;
                if (angle > 360) angle = 360;
                bgState.gradientAngle = angle;
                if (gradAngleLabel) gradAngleLabel.textContent = `${t('bg.angle')} ${Math.round(angle)}°`;
                saveBackgroundState(bgState);
                if (bgState.mode === 'gradient') {
                    applyBackgroundState(bgState);
                }
            }
        });
    }
    if (imageInput) {
        imageInput.addEventListener('change', (ev) => {
            const files = (ev.target as HTMLInputElement).files;
            if (files && files[0]) {
                const file = files[0];
                const reader = new FileReader();
                reader.onload = () => {
                    bgState.imageDataUrl = typeof reader.result === 'string' ? reader.result : null;
                    saveBackgroundState(bgState);
                    if (bgState.mode === 'image') {
                        applyBackgroundState(bgState);
                    }
                };
                reader.readAsDataURL(file);
            }
        });
    }
    if (imageClearBtn) {
        imageClearBtn.addEventListener('click', () => {
            bgState.imageDataUrl = null;
            saveBackgroundState(bgState);
            if (bgState.mode === 'image') {
                applyBackgroundState(bgState);
            }
            if (imageInput) {
                imageInput.value = '';
            }
        });
    }
    if (bgBtn && bgWindow) {
        bgBtn.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();
            const isVisible = bgWindow.getAttribute('aria-hidden') === 'false';
            const nextVisible = !isVisible;
            bgWindow.style.display = nextVisible ? 'block' : 'none';
            bgWindow.setAttribute('aria-hidden', String(!nextVisible));
        });
    }
    if (bgCloseBtn && bgWindow) {
        bgCloseBtn.addEventListener('click', () => {
            bgWindow.style.display = 'none';
            bgWindow.setAttribute('aria-hidden', 'true');
        });
    }

    const handleColorChange = (ev: Event) => {
        const color = (ev.target as HTMLInputElement).value || '#ffffff';
        bgState.mode = 'solid';
        bgState.solidColor = color;
        localStorage.setItem('app_bg_color', color);
        saveBackgroundState(bgState);
        applyBackgroundState(bgState);
    };

    (window as any).setLive2DBackgroundColor = (color: string) => {
        bgState.mode = 'solid';
        bgState.solidColor = color;
        localStorage.setItem('app_bg_color', color);
        saveBackgroundState(bgState);
        applyBackgroundState(bgState);
    };
    if (bgInput) {
        bgInput.addEventListener('input', handleColorChange);
        bgInput.addEventListener('change', handleColorChange);
    }
}
