import { LAppDelegate } from './delegation/delegate';
import setupMotionListUI from './ui/motionlist';
import setupParameterUI from './ui/parameters';
import { setupPartsUI } from './ui/parts';
import { setupImportModelUI } from './ui/import';
import { setupWorkspaceUI } from './ui/workspace';
import { setupExpressionUI } from './ui/expressions';
import { setupLipSyncUI } from './ui/lipsync';
import { setupControlBarUI } from './ui/controlbar';
import { setupHitAreaOverlayUI } from './ui/hitarea';
import { setupRecordingUI } from './ui/recording';
import { init as initI18n } from './i18n/index';

window.addEventListener(
  'load',
  (): void => {
    initI18n();
    setupMotionListUI();
    setupParameterUI();
    setupPartsUI();
    setupExpressionUI();
    setupLipSyncUI();
    setupHitAreaOverlayUI();
    setupControlBarUI();
    setupImportModelUI();
    setupWorkspaceUI();
    window.addEventListener('keydown', (e) => {
      const active = document.activeElement as HTMLElement | null;
      const isTyping = active && (active.tagName === 'INPUT' || active.tagName === 'TEXTAREA');
      if (isTyping) return;
      if (e.key === 'm' || e.key === 'M') {
        const toggleBtn = document.getElementById('toggle-window-btn') as HTMLButtonElement;
        if (toggleBtn) toggleBtn.click();
      }
      if (e.key === 'p' || e.key === 'P') {
        const toggleBtn = document.getElementById('toggle-params-btn') as HTMLButtonElement;
        if (toggleBtn) toggleBtn.click();
      }
      if (e.key === 't' || e.key === 'T') {
        const toggleBtn = document.getElementById('toggle-parts-btn') as HTMLButtonElement;
        if (toggleBtn) toggleBtn.click();
      }
      if (e.key === 'e' || e.key === 'E') {
        const toggleBtn = document.getElementById('toggle-expr-btn') as HTMLButtonElement;
        if (toggleBtn) toggleBtn.click();
      }
      if (e.key === 'h' || e.key === 'H') {
        const toggleBtn = document.getElementById('toggle-hitareas-btn') as HTMLButtonElement;
        if (toggleBtn) toggleBtn.click();
      }
      if (e.key === 'l' || e.key === 'L') {
        const toggleBtn = document.getElementById('toggle-lipsync-btn') as HTMLButtonElement;
        if (toggleBtn) toggleBtn.click();
      }
      if (e.key === 'b' || e.key === 'B') {
        const bgBtn = document.getElementById('btn-bg-picker') as HTMLButtonElement;
        if (bgBtn) bgBtn.click();
      }
      if (e.key === 'Escape') {
        const windows = ['motion-list-window', 'parameter-window', 'parts-window', 'expression-list-window', 'lipsync-window'];
        windows.forEach(id => {
          const window = document.getElementById(id) as HTMLDivElement;
          const btn = document.querySelector(`[aria-controls="${id}"]`) as HTMLButtonElement;
          if (window && window.style.display !== 'none' && btn) {
            btn.click();
          }
        });
      }
    });
    if (!LAppDelegate.getInstance().initialize()) {
      return;
    }
    LAppDelegate.getInstance().run();
  },
  {
    passive: true
  }
);
window.addEventListener(
  'beforeunload',
  (): void => LAppDelegate.releaseInstance(),
  {
    passive: true
  }
);

window.addEventListener('load', () => {
  setupRecordingUI();
});
