export class HighQualityRecorder {
    private mediaRecorder: MediaRecorder | null = null;
    private sourceCanvas: HTMLCanvasElement | null = null;
    private offscreenCanvas: OffscreenCanvas | null = null;
    private recordingStream: MediaStream | null = null;
    private recordedChunks: BlobPart[] = [];
    private isRecording = false;
    private isPaused = false;
  
    async initialize(sourceCanvas: HTMLCanvasElement, width: number, height: number): Promise<boolean> {
      try {
        this.sourceCanvas = sourceCanvas;
        this.offscreenCanvas = new OffscreenCanvas(width, height);
        
        let stream = (this.offscreenCanvas as any).captureStream ? 
          (this.offscreenCanvas as any).captureStream(60) : null;
        
        if (stream) {
          this.recordingStream = stream;
        } else {
          stream = (sourceCanvas as any).captureStream ? (sourceCanvas as any).captureStream(60) : null;
          if (stream) {
            this.recordingStream = stream;
          } else {
            console.error('[HighQualityRecorder] Canvas captureStream not supported.');
            return false;
          }
        }
        return true;
      } catch (e) {
        console.error('[HighQualityRecorder] Initialization failed:', e);
        return false;
      }
    }
  
    start(audioStream?: MediaStream): boolean {
      if (!this.recordingStream) return false;
      try {
        const width = this.sourceCanvas?.width || this.offscreenCanvas?.width || 1920;
        const height = this.sourceCanvas?.height || this.offscreenCanvas?.height || 1080;
        const pixelCount = width * height;
        let videoBitsPerSecond = Math.floor(pixelCount * 8 * 60 * 0.75);
        videoBitsPerSecond = Math.max(35000000, Math.min(80000000, videoBitsPerSecond));
  
        const hasAudio = audioStream && audioStream.getAudioTracks().length > 0;

        let codecCandidates: string[];
        if (hasAudio) {
          codecCandidates = [
            'video/webm;codecs=vp9,opus',
            'video/webm;codecs=vp8,opus',
            'video/webm;codecs=vp9',
            'video/webm;codecs=vp8',
            'video/webm'
          ];
        } else {
          codecCandidates = [
            'video/webm;codecs=av01.0.12M.08',
            'video/webm;codecs=vp9,profile0',
            'video/webm;codecs=vp9',
            'video/webm;codecs=vp8',
            'video/webm'
          ];
        }
  
        let mimeType = '';
        let selectedCodec = 'default';
        for (const candidate of codecCandidates) {
          if (MediaRecorder.isTypeSupported(candidate)) {
            mimeType = candidate;
            if (candidate.includes('av01')) selectedCodec = 'AV1';
            else if (candidate.includes('vp9')) selectedCodec = 'VP9';
            else if (candidate.includes('vp8')) selectedCodec = 'VP8';
            break;
          }
        }
  
        if (!mimeType) {
          mimeType = 'video/webm';
        }
  
        let targetStream: MediaStream = this.recordingStream;
        try {
          if (hasAudio) {
            const mixed = new MediaStream();
            this.recordingStream.getVideoTracks().forEach((t) => mixed.addTrack(t));
            audioStream!.getAudioTracks().forEach((t) => mixed.addTrack(t));
            targetStream = mixed;
          }
        } catch (e) {
          console.warn('[HighQualityRecorder] Failed to mix audio:', e);
        }
  
        const mrOptions: any = { videoBitsPerSecond } as any;
        if (mimeType) mrOptions.mimeType = mimeType;
        this.mediaRecorder = new MediaRecorder(targetStream, mrOptions);
        this.mediaRecorder.ondataavailable = (ev) => {
          if (ev.data && ev.data.size > 0) this.recordedChunks.push(ev.data);
        };
        this.isRecording = true;
        this.isPaused = false;
        this.mediaRecorder.start();
        return true;
      } catch (e) {
        console.error('[HighQualityRecorder] Failed to start:', e);
        return false;
      }
    }
  
    pause(): boolean {
      if (!this.mediaRecorder || !this.isRecording) return false;
      try {
        this.mediaRecorder.pause();
        this.isPaused = true;
        return true;
      } catch (e) {
        console.error('[HighQualityRecorder] Failed to pause:', e);
        return false;
      }
    }
  
    resume(): boolean {
      if (!this.mediaRecorder || !this.isPaused) return false;
      try {
        this.mediaRecorder.resume();
        this.isPaused = false;
        return true;
      } catch (e) {
        console.error('[HighQualityRecorder] Failed to resume:', e);
        return false;
      }
    }
  
    stop(): Promise<Blob | null> {
      if (!this.mediaRecorder || !this.isRecording) return Promise.resolve(null);
      return new Promise((resolve) => {
        if (!this.mediaRecorder) {
          resolve(null);
          return;
        }
        this.mediaRecorder.onstop = () => {
          const blob = new Blob(this.recordedChunks, { type: 'video/webm' });
          this.isRecording = false;
          resolve(blob);
        };
        this.mediaRecorder.stop();
      });
    }
  
    release(): void {
      this.mediaRecorder = null;
      this.sourceCanvas = null;
      this.offscreenCanvas = null;
      this.recordingStream = null;
      this.recordedChunks = [];
    }
  }