import { t } from '../i18n/index';
import { HighQualityRecorder } from "./recorder";
import { LAppDelegate } from "../delegation/delegate";
import { CubismMatrix44 } from '@framework/math/cubismmatrix44';

export function setupRecordingUI(): void {
    const startBtn = document.getElementById('rec-start-btn') as HTMLButtonElement | null;
    const pauseBtn = document.getElementById('rec-pause-btn') as HTMLButtonElement | null;
    const stopBtn = document.getElementById('rec-stop-btn') as HTMLButtonElement | null;
    const downloadLink = document.getElementById('rec-download-btn') as HTMLAnchorElement | null;
    const timerEl = document.getElementById('rec-timer') as HTMLDivElement | null;
    const recordingWindow = document.getElementById('recording-window') as HTMLDivElement | null;
    const toggleRecBtn = document.getElementById('toggle-recording-btn') as HTMLButtonElement | null;
    const photoBtn = document.getElementById('rec-photo-btn') as HTMLButtonElement | null;
    const settingsBtn = document.getElementById('rec-settings-btn') as HTMLButtonElement | null;
    const settingsPanel = document.getElementById('recording-settings-panel') as HTMLDivElement | null;
    if (!startBtn || !pauseBtn || !stopBtn || !downloadLink || !timerEl || !recordingWindow || !photoBtn) {
      console.error('[RecordingUI] Elements not found. Skipping setup.');
      return;
    }
    if (!toggleRecBtn) {
      console.warn('[RecordingUI] Toggle button not found; recording window cannot be toggled via control bar.');
    }
    let recorder: HighQualityRecorder | null = null;
    let timerInterval: number | null = null;
    let startTime = 0;
    let audioContext: AudioContext | null = null;
    let audioDestination: MediaStreamAudioDestinationNode | null = null;
    let audioPatchApplied = false;
    function ensureAudioCapture(): void {
      if (audioPatchApplied) return;
      audioPatchApplied = true;
      try {
        const OriginalAudio = (window as any).Audio;
        if (!OriginalAudio) {
          console.warn('[RecordingUI] window.Audio not available to patch.');
          return;
        }
        const ACtor: any = window.AudioContext || (window as any).webkitAudioContext;
        try {
          audioContext = new ACtor({ sampleRate: 48000 });
        } catch (e) {
          audioContext = new ACtor();
        }
        audioDestination = audioContext.createMediaStreamDestination();
        (window as any).Audio = function (src?: string) {
          const el = new OriginalAudio(src);
          try {
            const srcNode = audioContext!.createMediaElementSource(el);
            srcNode.connect(audioContext!.destination);
            srcNode.connect(audioDestination!);
          } catch (e) {
            console.warn('[RecordingUI] Could not create media element source for audio element:', e);
          }
          return el;
        } as any;
        (window as any).Audio.prototype = OriginalAudio.prototype;
        document.querySelectorAll('audio').forEach((el) => {
          try {
            const node = audioContext!.createMediaElementSource(el as HTMLAudioElement);
            node.connect(audioContext!.destination);
            node.connect(audioDestination!);
          } catch (e) {
          }
        });
      } catch (e) {
        console.warn('[RecordingUI] Audio capture setup failed:', e);
        audioContext = null;
        audioDestination = null;
        audioPatchApplied = false;
      }
    }
    function updateTimer(): void {
      const elapsed = Math.max(0, Math.floor((performance.now() - startTime) / 1000));
      const mm = String(Math.floor(elapsed / 60)).padStart(2, '0');
      const ss = String(elapsed % 60).padStart(2, '0');
      if (timerEl) timerEl.textContent = `${mm}:${ss}`;
    }
    function enableDownload(blob: Blob) {
      const url = URL.createObjectURL(blob);
      downloadLink.href = url;
      downloadLink.classList.remove('disabled');
      downloadLink.removeAttribute('aria-disabled');
    }
    async function startRecording(): Promise<void> {
      let canvas: HTMLCanvasElement | null = null;
      try {
        const appDelegate = LAppDelegate.getInstance();
        const subs = appDelegate.getSubdelegates();
        for (let i = 0; i < subs.length; i++) {
          try {
            const sub = subs[i] as any;
            const liveMgr = sub.getLive2DManager && sub.getLive2DManager();
            const currentModel = liveMgr && typeof liveMgr.getCurrentModel === 'function' ? liveMgr.getCurrentModel() : null;
            if (currentModel && currentModel.getModel && currentModel.getModel()) {
              canvas = sub.getCanvas();
              break;
            }
          } catch (e) {
          }
        }
        if (!canvas) {
          for (let i = 0; i < subs.length; i++) {
            try {
              const c = subs[i].getCanvas();
              if (c && c.clientWidth > 0 && c.clientHeight > 0 && c.offsetParent !== null) {
                canvas = c;
                break;
              }
            } catch (e) {}
          }
        }
      } catch (e) {
      }
  
      if (!canvas) {
        canvas = document.querySelector('canvas') as HTMLCanvasElement | null;
      }
      if (!canvas) {
        alert(t('rec.noCanvas'));
        return;
      }
  
      document.body.classList.add('recording');
      recorder = new HighQualityRecorder();
      const initialized = await recorder.initialize(canvas, canvas.width, canvas.height);
      if (!initialized) {
        alert(t('rec.initFail'));
        document.body.classList.remove('recording');
        recorder.release();
        recorder = null;
        return;
      }
  
      const includeAudioCheckbox = document.getElementById('rec-include-audio') as HTMLInputElement | null;
      const includeAudio = includeAudioCheckbox?.checked === true;
      if (includeAudio) {
        ensureAudioCapture();
        if (audioContext) {
          try { await audioContext.resume(); } catch (e) {  }
        }
      }
  
      if (!recorder.start(includeAudio && audioDestination ? audioDestination.stream : undefined)) {
        alert(t('rec.startFail'));
        document.body.classList.remove('recording');
        recorder.release();
        recorder = null;
        return;
      }
  
      startBtn.disabled = true;
      pauseBtn.disabled = false;
      stopBtn.disabled = false;
      downloadLink.classList.add('disabled');
      downloadLink.href = '#';
      downloadLink.setAttribute('aria-disabled', 'true');
      startTime = performance.now();
      updateTimer();
      timerInterval = window.setInterval(updateTimer, 250);
    }
    function pauseRecording(): void {
      if (!recorder) return;
      if (recorder.pause()) {
        pauseBtn.textContent = '▶';
        pauseBtn.title = t('rec.resume');
      }
    }
    function resumeRecording(): void {
      if (!recorder) return;
      if (recorder.resume()) {
        pauseBtn.textContent = '⏸';
        pauseBtn.title = t('rec.pause');
      }
    }
    async function stopRecording(): Promise<void> {
      if (!recorder) return;
      const blob = await recorder.stop();
      if (blob) {
        enableDownload(blob);
      }
      document.body.classList.remove('recording');
      if (timerInterval) {
        clearInterval(timerInterval);
        timerInterval = null;
      }
      startBtn.disabled = false;
      pauseBtn.disabled = true;
      stopBtn.disabled = true;
      pauseBtn.textContent = '⏸';
      pauseBtn.title = 'Pause Recording';
      recorder.release();
      recorder = null;
    }
    async function renderModelToCanvas(
      model: any,
      liveCanvas: HTMLCanvasElement,
      sub: any,
      scale: number | string = 1
    ): Promise<HTMLCanvasElement | null> {
      try {
        const w = liveCanvas.width;
        const h = liveCanvas.height;
        if (w === 0 || h === 0) return null;

        const gl = sub.getGlManager()?.getGl?.();
        if (!gl) return null;

        let tw = w;
        let th = h;
        if (scale === '4k') {
          tw = 3840;
          th = Math.round((h / w) * tw);
        } else if (scale === '8k') {
          tw = 7680;
          th = Math.round((h / w) * tw);
        } else {
          const mult = typeof scale === 'number' ? scale : 1;
          tw = w * mult;
          th = h * mult;
        }

        const maxTex = gl.getParameter(gl.MAX_TEXTURE_SIZE) || 4096;
        const maxSide = Math.max(tw, th);
        if (maxSide > maxTex) {
          const k = maxTex / maxSide;
          tw = Math.max(1, Math.floor(tw * k));
          th = Math.max(1, Math.floor(th * k));
        }
        const sw = Math.max(1, tw);
        const sh = Math.max(1, th);

        if (sw * sh > 512 * 1024 * 1024) {
          return null;
        }

        const tex = gl.createTexture();
        gl.bindTexture(gl.TEXTURE_2D, tex);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, sw, sh, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
        const fbo = gl.createFramebuffer();
        const prevFbo = gl.getParameter(gl.FRAMEBUFFER_BINDING);
        gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
        gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, tex, 0);
        gl.clearColor(0, 0, 0, 0);
        gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);

        const projection = new CubismMatrix44();
        const m = model.getModel();
        const matrix = model.getModelMatrix();
        if (m.getCanvasWidth() > 1.0 && w < h) {
          matrix.setWidth(2.0);
          projection.scale(1.0, w / h);
        } else {
          projection.scale(h / w, 1.0);
        }
        const view = sub.getView();
        if (view && (view as any)._viewMatrix) {
          projection.multiplyByMatrix((view as any)._viewMatrix);
        }
        projection.multiplyByMatrix(matrix);

        const renderer = model.getRenderer();
        renderer.setRenderState(fbo, [0, 0, sw, sh]);
        renderer.setMvpMatrix(projection);
        renderer.drawModel();
        gl.finish();

        const pixels = new Uint8Array(sw * sh * 4);
        gl.readPixels(0, 0, sw, sh, gl.RGBA, gl.UNSIGNED_BYTE, pixels);

        gl.bindFramebuffer(gl.FRAMEBUFFER, prevFbo);
        gl.deleteFramebuffer(fbo);
        gl.deleteTexture(tex);

        const big = document.createElement('canvas');
        big.width = sw;
        big.height = sh;
        const bctx = big.getContext('2d');
        if (!bctx) return null;
        const flipped = bctx.createImageData(sw, sh);
        for (let y = 0; y < sh; y++) {
          const srcRow = (sh - 1 - y) * sw * 4;
          const dstRow = y * sw * 4;
          flipped.data.set(pixels.subarray(srcRow, srcRow + sw * 4), dstRow);
        }
        bctx.putImageData(flipped, 0, 0);
        return big;
      } catch (e) {
        console.warn('[RecordingUI] Transparent render failed:', e);
        return null;
      }
    }

    async function takeSnapshot(): Promise<void> {
      let canvas: HTMLCanvasElement | null = null;
      let sub: any = null;
      let model: any = null;
      try {
        const appDelegate = LAppDelegate.getInstance();
        const subs = appDelegate.getSubdelegates();
        if (subs && subs.length > 0) {
          sub = subs[0];
          if (sub && typeof sub.getCanvas === 'function') {
            canvas = sub.getCanvas();
          }
          if (sub && typeof sub.getLive2DManager === 'function') {
            const liveMgr = sub.getLive2DManager();
            model =
              liveMgr && typeof liveMgr.getCurrentModel === 'function'
                ? liveMgr.getCurrentModel()
                : null;
          }
        }
      } catch (e) {
        console.warn('[RecordingUI] Failed to resolve Live2D canvas from delegate, falling back to first <canvas>.', e);
      }
      if (!canvas) {
        canvas = document.querySelector('canvas') as HTMLCanvasElement | null;
      }
      if (!canvas) {
        alert(t('rec.noCanvas'));
        return;
      }
      if (!model || !model.getRenderer) {
        alert(t('rec.snapshotFail'));
        return;
      }

      try {
        const gl = sub?.getGlManager?.()?.getGl?.();
        if (gl && typeof gl.finish === 'function') {
          gl.finish();
        }
      } catch (e) {
      }

      const transparentBg = (document.getElementById('rec-transparent-bg') as HTMLInputElement | null)?.checked === true;
      const resSel = document.getElementById('rec-resolution') as HTMLSelectElement | null;
      const resVal: string = resSel?.value || '2x';

      let source: HTMLCanvasElement | null;
      if (transparentBg) {
        source = await renderModelToCanvas(model, canvas, sub, resVal);
      } else {
        let tw = canvas.width;
        let th = canvas.height;
        if (resVal === '4k') {
          tw = 3840;
          th = Math.round((canvas.height / canvas.width) * tw);
        } else if (resVal === '8k') {
          tw = 7680;
          th = Math.round((canvas.height / canvas.width) * tw);
        } else {
          const mult = parseFloat(resVal.replace('x', '')) || 1;
          tw = canvas.width * mult;
          th = canvas.height * mult;
        }
        source = document.createElement('canvas');
        source.width = Math.max(1, tw);
        source.height = Math.max(1, th);
        const ctx = source.getContext('2d');
        if (ctx) {
          ctx.imageSmoothingEnabled = true;
          ctx.imageSmoothingQuality = 'high';
          ctx.drawImage(
            canvas,
            0,
            0,
            canvas.width,
            canvas.height,
            0,
            0,
            source.width,
            source.height
          );
        }
      }
      if (!source) {
        alert(t('rec.snapshotFail'));
        return;
      }

      const blob: Blob | null = await new Promise((resolve) =>
        source.toBlob((b) => resolve(b), 'image/png')
      );
      if (!blob) {
        alert(t('rec.snapshotFail2'));
        return;
      }
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      const now = new Date();
      const ts = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(
        now.getDate()
      ).padStart(2, '0')}_${String(now.getHours()).padStart(2, '0')}-${String(
        now.getMinutes()
      ).padStart(2, '0')}-${String(now.getSeconds()).padStart(2, '0')}`;
      a.href = url;
      a.download = `live2d_snapshot_${ts}.png`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      setTimeout(() => URL.revokeObjectURL(url), 5000);
    }
    startBtn.addEventListener('click', () => startRecording());
    pauseBtn.addEventListener('click', () => {
      if (recorder) {
        if (pauseBtn.textContent === '⏸') {
          pauseRecording();
        } else {
          resumeRecording();
        }
      }
    });
    stopBtn.addEventListener('click', () => stopRecording());
    photoBtn.addEventListener('click', () => { void takeSnapshot(); });
    const setSettingsOpen = (open: boolean) => {
      if (!settingsBtn || !settingsPanel) return;
      settingsPanel.classList.toggle('hidden', !open);
      settingsPanel.setAttribute('aria-hidden', String(!open));
      settingsBtn.setAttribute('aria-pressed', String(open));
      settingsBtn.setAttribute('aria-expanded', String(open));
    };
    settingsBtn?.addEventListener('click', () => {
      const isOpen = settingsPanel?.classList.contains('hidden') === false;
      setSettingsOpen(!isOpen);
    });
    toggleRecBtn?.addEventListener('click', () => {
      const isHidden = recordingWindow.classList.contains('hidden');
      recordingWindow.classList.toggle('hidden', !isHidden);
      recordingWindow.setAttribute('aria-hidden', String(!isHidden));
      toggleRecBtn?.setAttribute('aria-pressed', String(isHidden));
      if (!isHidden) {
        setSettingsOpen(false);
      }
    });
    if (settingsPanel && settingsBtn) {
      const closeSettings = () => setSettingsOpen(false);
      startBtn.addEventListener('click', closeSettings);
      stopBtn.addEventListener('click', closeSettings);
      photoBtn.addEventListener('click', closeSettings);
      downloadLink.addEventListener('click', closeSettings);
    }
    const stopProp = (ev: Event) => { ev.stopPropagation(); };
    const interactiveEls = [startBtn, pauseBtn, stopBtn, photoBtn, downloadLink, recordingWindow, toggleRecBtn];
    if (settingsBtn) interactiveEls.push(settingsBtn);
    if (settingsPanel) interactiveEls.push(settingsPanel);
    interactiveEls.forEach((el) => {
      if (!el) return;
      el.addEventListener('pointerdown', stopProp, { passive: true } as AddEventListenerOptions);
      el.addEventListener('pointerup', stopProp, { passive: true } as AddEventListenerOptions);
      el.addEventListener('pointerleave', stopProp, { passive: true } as AddEventListenerOptions);
      el.addEventListener('touchstart', stopProp, { passive: true } as AddEventListenerOptions);
      el.addEventListener('touchend', stopProp, { passive: true } as AddEventListenerOptions);
      el.addEventListener('click', stopProp);
    });
    downloadLink.addEventListener('click', () => {
      const href = downloadLink.href;
      setTimeout(() => {
        try { URL.revokeObjectURL(href); } catch (e) {}
      }, 2000);
    });
    (window as any).startAutoRecording = async () => {
      if (recorder) {
        console.warn('[RecordingUI] ' + t('rec.recordingInProgress'));
        return;
      }
      await startRecording();
    };
    (window as any).stopAutoRecording = () => {
      stopRecording();
    };
  }