import { translations, type Locale, localeLabels } from './translations';

const STORAGE_KEY = 'app_locale';
const listeners: Array<() => void> = [];
let currentLocale: Locale = 'en';

function detectBrowserLocale(): Locale {
  const langs = navigator.languages || [navigator.language];
  for (const l of langs) {
    const code = l.toLowerCase().replace('-', '-');
    if (code === 'ja' || code.startsWith('ja-')) return 'ja';
    if (code === 'zh-cn' || code === 'zh-hans-cn') return 'zh-hans';
    if (code === 'zh-tw' || code === 'zh-hk' || code === 'zh-hant-tw') return 'zh-hant';
    if (code === 'ko' || code.startsWith('ko-')) return 'kr';
    if (code === 'en' || code.startsWith('en-')) return 'en';
  }
  return 'en';
}

export function getLocale(): Locale {
  return currentLocale;
}

export function getLocales(): { code: Locale; label: string }[] {
  return Object.entries(localeLabels).map(([code, label]) => ({
    code: code as Locale,
    label,
  }));
}

export function t(key: string, fallback?: string): string {
  const dict = translations[currentLocale];
  const val = dict?.[key];
  if (val !== undefined) return val;
  const enVal = translations.en[key];
  if (enVal !== undefined) return enVal;
  return fallback ?? key;
}

export function onLocaleChange(fn: () => void): void {
  listeners.push(fn);
}

function reTranslateDom(): void {
  document.querySelectorAll<HTMLElement>('[data-i18n]').forEach((el) => {
    const key = el.getAttribute('data-i18n');
    if (key) el.textContent = t(key, el.textContent || undefined);
  });
  document.querySelectorAll<HTMLElement>('[data-i18n-title]').forEach((el) => {
    const key = el.getAttribute('data-i18n-title');
    if (key) el.title = t(key, el.title || undefined);
  });
  document.querySelectorAll<HTMLElement>('[data-i18n-aria-label]').forEach((el) => {
    const key = el.getAttribute('data-i18n-aria-label');
    if (key) el.setAttribute('aria-label', t(key, el.getAttribute('aria-label') || undefined));
  });
  document.querySelectorAll<HTMLElement>('[data-i18n-placeholder]').forEach((el) => {
    const key = el.getAttribute('data-i18n-placeholder');
    if (key) (el as HTMLInputElement).placeholder = t(key, (el as HTMLInputElement).placeholder || undefined);
  });
  document.querySelectorAll<HTMLMetaElement>('[data-i18n-content]').forEach((el) => {
    const key = el.getAttribute('data-i18n-content');
    if (key) el.content = t(key, el.content || undefined);
  });
  const select = document.getElementById('locale-select') as HTMLSelectElement | null;
  if (select) select.value = currentLocale;
}

export function setLocale(locale: Locale): void {
  if (!translations[locale]) return;
  currentLocale = locale;
  localStorage.setItem(STORAGE_KEY, locale);
  document.documentElement.lang = locale;
  reTranslateDom();
  listeners.forEach((fn) => fn());
}

export function init(): void {
  const stored = localStorage.getItem(STORAGE_KEY) as Locale | null;
  const locale = stored || detectBrowserLocale();
  const select = document.getElementById('locale-select') as HTMLSelectElement | null;
  if (select) {
    select.innerHTML = '';
    getLocales().forEach(({ code, label }) => {
      const opt = document.createElement('option');
      opt.value = code;
      opt.textContent = label;
      select.appendChild(opt);
    });
    select.addEventListener('change', () => {
      const val = select.value as Locale;
      if (val && translations[val]) setLocale(val);
    });
  }
  onLocaleChange(() => {
    const titleEl = document.querySelector('title[data-i18n]');
    if (titleEl) {
      const key = titleEl.getAttribute('data-i18n');
      if (key) titleEl.textContent = t(key);
    }
  });
  setLocale(locale);
}
